import taf.collectors.core as collectors_core
import taf.collectors.aashell_cli as aashell_cli
import taf.collectors.aashell_log as aashell_log

from typing import Optional


class AashellLogCollector:
    def __init__(self, vm: dict, secondary_vm: dict, node_enb_ip: str = "192.168.255.129"):
        self.vm = vm
        self.secondary_vm = secondary_vm
        self.node_enb_ip = node_enb_ip
        self._core = collectors_core.CollectorKeywords()
        self.aashell_cli = aashell_cli.aashell_cli()
        self.aashell_log = aashell_log.aashell_log()

    def get_snapshot_from_aashell(self, target_dir: Optional[str] = None, target_file_name: Optional[str] = None,
                                  timeout: Optional[int] = 300, alias: Optional[str] = "aashell_log"):
        vm_details = [vm for vm in [self.vm, self.secondary_vm] if vm]
        alias_list = []
        for vm in vm_details:
            if isinstance(vm, dict) and 'bts_host_ip' in vm:
                del vm['bts_host_ip']
            aashell_cli_name = "aashell_cli"
            collector_name = f"{alias}_{vm.get('host')}"
            alias_list.append(collector_name)
            self.aashell_cli.create_aashell_cli(name=aashell_cli_name, hops=dict(host=self.node_enb_ip, proxy=vm))
            self.aashell_log.create_aashell_log_collector(name=collector_name, tool=aashell_cli_name,
                                                          target_file_name=target_file_name, timeout=timeout)
        str_aliases = ",".join(alias_list)
        try:
            self._core.setup_collectors(names=str_aliases)
            self._core.collect_collectors(names=str_aliases, target_dir=target_dir)
        finally:
            self._core.teardown_collectors(names=str_aliases)
